const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = data[0];
const A = data.slice(1, 1 + n);

const ans = new Array(n);
const left = new Array(n);

let best = Infinity;
for (let i = 0; i < n; i++) {
    if (A[i] !== -1) {
        const v = A[i] - (i + 1);
        if (v < best) best = v;
    }
    left[i] = (i + 1) + best;
}

best = Infinity;
for (let i = n - 1; i >= 0; i--) {
    if (A[i] !== -1) {
        const v = A[i] + (i + 1);
        if (v < best) best = v;
    }
    const right = -(i + 1) + best;
    ans[i] = Math.min(left[i], right);
}

console.log(ans.join(' '));
